import React, { Component } from 'react'
import {Dimensions, Image, Text, TouchableWithoutFeedback, View, Button, TouchableNativeFeedback, BackHandler} from 'react-native'
import styles from './TestStyles';
import SnapCarousel from 'react-native-snap-carousel';
import {NavigationActions} from 'react-navigation';
import axios from "axios/index";
const screen = Dimensions.get('window');
  vh = screen.height / 100;
  vw = screen.width / 100;

class testPerformance extends Component {

  static navigationOptions = ({ navigation }) => ({
    header : null
  })

  constructor() {
    super();
    this.state = {
      totalScore: 0,
      correct: 0,
      wrong: 0,
      skipped: 0,
    }
    this.handleBackButton = this.handleBackButton.bind(this);
  }

  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  calculateScore() {
    totalScore = 0;
    correct = 0;
    wrong = 0;
    skipped = 0;
    this.props.navigation.state.params.answer.map((blocks, index) => {
      console.log("sdnsadsk: "+JSON.stringify(blocks.score));
      totalScore += blocks.score;
      if(blocks.score == 4) {
        correct += 1
      }
      else if(blocks.score == -1) {
        wrong += 1
      }
      
    });
    this.setState({correct: correct});
    this.setState({wrong: wrong});
    this.setState({totalScore: totalScore});
  }

  handleBackButton() {
    console.log("workingjdh");
    this.props.navigation.navigate('HomeStack', {}, NavigationActions.navigate({ routeName: 'Home' }));
    return true;
  }

  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  async componentDidMount() {
    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
    await this.calculateScore();
    console.log("LKHSCFSJS: "+this.state.correct);
    var data ={
      "points": this.state.correct * 4
    }
    axios.post(`https://classcast-198812.appspot.com/performance/store/`, data)
    .then((response) => 
              {
                 console.log("API response" + JSON.stringify(response))
              })
              .catch((error) => {
                  console.log("API error" + error)
              })
  }

  render() {
    console.log("JHGDS: "+JSON.stringify(this.props.navigation.state.params.answer));
    console.log("JHGDS: "+JSON.stringify(this.props.navigation.state.params.answer))
    return (
      <View style={styles.container}>
      <Image
          style={{
            position: 'absolute',
            flex: 1,
            width: '100%',
            height: '100%',
          }}
          source={{uri: 'data:image/jpeg;base64,'}}
        />
        <View style={{flexDirection: 'row',}}>
        <Text style={[styles.rightSplitText], {fontSize: 12 * vh, color: 'white', marginTop: 1 * vh, marginLeft: 8 * vw,}}>{this.state.totalScore}</Text>
        <View style={{flexDirection: 'column',}}>
          <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white', marginTop: 3.8 * vh, marginLeft: 1 * vw, }}>SCORE</Text>
        <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white', marginLeft: 1 * vw }}>/ {this.props.navigation.state.params.blocks.length * 4}</Text>
        </View>
        </View>
        <View style = {{marginTop: 30 * vh, flexDirection: 'row', height: 13 * vh, width: 100*vw}}>
          <View style={{ flexDirection: 'column', height: 10 * vh, width: 25*vw, marginLeft: 17 * vw, justifyContent: 'center', alignItems: 'center'}}>
            <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white' }}>{this.state.correct}</Text>
            <Text style={[styles.rightSplitText], {fontSize: 2 * vh, color: 'white' }}>Correct</Text>
          </View>
          <View style={{ flexDirection: 'column', height: 10 * vh, width: 25*vw, marginLeft: 3 * vw, justifyContent: 'center', alignItems: 'center'}}>
            <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white' }}>{this.state.skipped}</Text>
            <Text style={[styles.rightSplitText], {fontSize: 2 * vh, color: 'white' }}>Skipped</Text>
          </View>
          <View style={{ flexDirection: 'column', height: 10 * vh, width: 25*vw, marginLeft: 3 * vw, justifyContent: 'center', alignItems: 'center'}}>
            <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white' }}>{this.state.wrong}</Text>
            <Text style={[styles.rightSplitText], {fontSize: 2 * vh, color: 'white' }}>Wrong</Text>
          </View>
        </View>
        <View style={{ height: 10 * vh, width: '70%', justifyContent: 'center', alignItems: 'center', marginLeft: 30 * vw, marginTop: 3.8 * vh}}>
        <Text style={[styles.rightSplitText], {fontSize: 3.5 * vh, color: 'white'}}>{Math.floor(this.props.navigation.state.params.timer/60)}:{(this.props.navigation.state.params.timer % 60) > 9 ? this.props.navigation.state.params.timer % 60 : '0'+ this.props.navigation.state.params.timer % 60} Minutes</Text>
        </View>
        <View style={{height: 7 * vh, width: '100%', marginTop: 6.8 * vh, flexDirection: 'row'}}>
          <TouchableNativeFeedback
              onPress={() => {
                const navigateAction = NavigationActions.navigate({
                  routeName: 'reviewTest',
                  params: {
                    blocks: this.props.navigation.state.params.blocks,
                    answer: this.props.navigation.state.params.answer,
                  },
                });
                this.props.navigation.dispatch(navigateAction);

              }}
            >
            <View style={{height : 7 * vh, width: 25 * vw, marginLeft: 5 * vh, justifyContent: 'center', alignItems: 'center'}}>
              <Text style={[styles.rightSplitText], {fontSize: 3 * vh, color: 'white' }}>Review</Text>
            </View>
          </TouchableNativeFeedback>
          <TouchableNativeFeedback
              onPress={() => {
            this.props.navigation.navigate('test2')
          }}
            >
            <View style={{height : 7 * vh, width: 35 * vw, marginLeft: 26 * vw, justifyContent: 'center', alignItems: 'center'}}>
              <Text style={[styles.rightSplitText], {fontSize: 3 * vh, color: 'white' }}>Another Test</Text>
            </View>
            </TouchableNativeFeedback>
        </View>
        <TouchableNativeFeedback
          onPress={() => {
            this.props.navigation.navigate('HomeStack', {}, NavigationActions.navigate({ routeName: 'Home' }))
          }}
            >
          <View style={{position: 'absolute', marginTop: 87 * vh, height: 10 * vh, width: '100%', backgroundColor: 'indigo', justifyContent: 'center', alignItems: 'center'}}>
            <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white' }}>Back to main menu</Text>
          </View>
        </TouchableNativeFeedback>

      </View>
    )
  }

}

export default testPerformance
